package cn.haiduo;
import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.mock.web.MockHttpSession;import org.springframework.web.server.ResponseStatusException;
import org.testcontainers.postgresql.PostgreSQLContainer;import org.flywaydb.core.Flyway;import cn.haiduo.inventory.InventoryService;
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="RUN_DATABASE_TESTS",matches="true")
class CorrectionContainerTest {
 static PostgreSQLContainer pg;static JdbcTemplate db;static TransactionTemplate tx;UUID tenant,sku,order;MockHttpSession session;InventoryService inventory;InventoryCorrections api;final UUID warehouse=UUID.fromString("00000000-0000-0000-0000-000000000001");
 @BeforeAll static void start(){pg=new PostgreSQLContainer("postgres:17.6").withDatabaseName("haiduo").withUsername("haiduo").withPassword("test-password");pg.start();var ds=new DriverManagerDataSource(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword());Flyway.configure().dataSource(ds).load().migrate();db=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));}
 @AfterAll static void stop(){if(pg!=null)pg.stop();}
 @BeforeEach void setup(){tenant=UUID.randomUUID();sku=UUID.randomUUID();order=UUID.randomUUID();db.update("insert into tenant values(?,'corrections')",tenant);db.update("insert into warehouse values(?,?,'default')",tenant,warehouse);db.update("insert into product(id,tenant_id,name) values(?,?,'test')",sku,tenant);db.update("insert into sku(id,tenant_id,code,name,cost,product_id) values(?,?,'A','test',200,?)",sku,tenant,sku);db.update("insert into inventory(tenant_id,sku_id,on_hand,reserved,warehouse_id) values(?,?,100,0,?)",tenant,sku,warehouse);db.update("insert into store(id,tenant_id,name,platform,connection_status) values(?,?,'mock','MOCK','MOCK')",UUID.randomUUID(),tenant);db.update("insert into sales_order(id,tenant_id,store,external_id,net,rate,currency,rate_source,rate_at,warehouse_id) values(?,?,'mock','ORDER',100,7.2,'USD','test',now(),?)",order,tenant,warehouse);db.update("insert into order_item(tenant_id,order_id,sku_id,quantity,unit_cost_cny) values(?,?,?,2,200)",tenant,order,sku);for(String user:List.of("requester","reviewer","finance")){db.update("insert into app_user(username,password_hash) values(?,'unused') on conflict do nothing",user);db.update("insert into membership values(?,?,?)",user,tenant,user.equals("finance")?"FINANCE":"WAREHOUSE");db.update("insert into member_grade values(?,?,?)",tenant,user,user.equals("requester")?1:3);}inventory=new InventoryService(db);api=new InventoryCorrections(db,new OperationsController(db,new SessionController(db),inventory),inventory);session=new MockHttpSession();session.setAttribute("activeTenant",tenant.toString());}
 UUID submit(String kind,UUID target){return submit(kind,target,UUID.randomUUID());}
 UUID submit(String kind,UUID target,UUID key){var result=tx.execute(s->api.submit(new InventoryCorrections.Request(kind,target,"test reason",key),()->"requester",session));return (UUID)((Map<?,?>)result).get("id");}
 Object decide(UUID id,String action,String user){return tx.execute(s->api.decide(id,new InventoryCorrections.Decision(action,"review"),()->user,session));}
 void transition(String action){tx.executeWithoutResult(s->inventory.transition(tenant,order,action));}
 int stock(String column){return db.queryForObject("select "+column+" from inventory where tenant_id=? and sku_id=?",Integer.class,tenant,sku);}
 String status(){return db.queryForObject("select status from sales_order where id=?",String.class,order);}
 UUID receipt(int quantity){UUID key=UUID.randomUUID();db.update("insert into stock_receipt(tenant_id,request_key,sku_id,quantity,warehouse_id) values(?,?,?,?,?)",tenant,key,sku,quantity,warehouse);db.update("update inventory set on_hand=on_hand+? where tenant_id=? and sku_id=?",quantity,tenant,sku);return key;}
 @Test void releaseCyclesCanReserveAndShipAgain(){transition("reserve");UUID id=submit("RELEASE",order);assertEquals(2,stock("reserved"));assertEquals(403,assertThrows(ResponseStatusException.class,()->decide(id,"approve","requester")).getStatusCode().value());for(int i=0;i<10;i++)decide(id,"approve","reviewer");assertEquals("NEW",status());assertEquals(0,stock("reserved"));assertEquals(100,stock("on_hand"));transition("reserve");UUID next=submit("RELEASE",order);decide(next,"approve","reviewer");transition("reserve");transition("ship");assertEquals("SHIPPED",status());assertEquals(98,stock("on_hand"));assertEquals(6,db.queryForObject("select count(*) from inventory_movement where tenant_id=?",Integer.class,tenant));}
 @Test void changedOrderMakesApprovalStale(){transition("reserve");UUID id=submit("RELEASE",order);transition("ship");decide(id,"approve","reviewer");assertEquals("STALE",db.queryForObject("select status from inventory_correction where id=?",String.class,id));assertEquals(98,stock("on_hand"));}
 @Test void duplicateRequestsAndConcurrentReversalApplyOnce(){UUID receipt=receipt(10),key=UUID.randomUUID(),id=submit("RECEIPT_REVERSE",receipt,key);for(int i=0;i<10;i++)assertEquals(id,submit("RECEIPT_REVERSE",receipt,key));java.util.stream.IntStream.range(0,10).parallel().forEach(i->decide(id,"approve","reviewer"));assertEquals(100,stock("on_hand"));assertEquals(1,db.queryForObject("select count(*) from receipt_reversal where tenant_id=?",Integer.class,tenant));assertEquals(1,db.queryForObject("select count(*) from stock_receipt where tenant_id=?",Integer.class,tenant));}
 @Test void insufficientAvailableStockRollsBackAndRejectsWrongRole(){UUID receipt=receipt(110),id=submit("RECEIPT_REVERSE",receipt);db.update("update inventory set reserved=150 where tenant_id=? and sku_id=?",tenant,sku);assertThrows(ResponseStatusException.class,()->decide(id,"approve","finance"));assertEquals(409,assertThrows(ResponseStatusException.class,()->decide(id,"approve","reviewer")).getStatusCode().value());assertEquals(210,stock("on_hand"));assertEquals(150,stock("reserved"));assertEquals("PENDING",db.queryForObject("select status from inventory_correction where id=?",String.class,id));assertEquals(0,db.queryForObject("select count(*) from receipt_reversal where tenant_id=?",Integer.class,tenant));}
 @Test void withdrawalExpiryAndTenantIsolation(){UUID receipt=receipt(1),id=submit("RECEIPT_REVERSE",receipt);decide(id,"withdraw","requester");decide(id,"approve","reviewer");assertEquals(101,stock("on_hand"));UUID expired=submit("RECEIPT_REVERSE",receipt);db.update("update inventory_correction set expires_at=now()-interval '1 second' where id=?",expired);decide(expired,"approve","reviewer");assertEquals("EXPIRED",db.queryForObject("select status from inventory_correction where id=?",String.class,expired));UUID other=UUID.randomUUID();db.update("insert into tenant values(?,'other')",other);db.update("insert into membership values('reviewer',?,'WAREHOUSE')",other);session.setAttribute("activeTenant",other.toString());assertEquals(404,assertThrows(ResponseStatusException.class,()->decide(id,"approve","reviewer")).getStatusCode().value());}
 @Test void multiSkuReleaseRollsBackAllLines(){UUID second=UUID.fromString("ffffffff-ffff-ffff-ffff-ffffffffffff");db.update("insert into sku(id,tenant_id,code,name,cost,product_id) values(?,?,'B','second',10,?)",second,tenant,sku);db.update("insert into inventory(tenant_id,sku_id,on_hand,reserved,warehouse_id) values(?,?,100,0,?)",tenant,second,warehouse);db.update("insert into order_item(tenant_id,order_id,sku_id,quantity,unit_cost_cny) values(?,?,?,3,10)",tenant,order,second);transition("reserve");UUID id=submit("RELEASE",order);db.update("update inventory set reserved=0 where tenant_id=? and sku_id=?",tenant,second);assertEquals(409,assertThrows(ResponseStatusException.class,()->decide(id,"approve","reviewer")).getStatusCode().value());assertEquals(2,stock("reserved"));assertEquals("RESERVED",status());assertEquals(0,db.queryForObject("select count(*) from inventory_movement where tenant_id=? and kind='release'",Integer.class,tenant));}
 @Test void twoApplicationsCannotReverseSameReceiptTwice(){UUID receipt=receipt(10),first=submit("RECEIPT_REVERSE",receipt),second=submit("RECEIPT_REVERSE",receipt);decide(first,"approve","reviewer");decide(second,"approve","reviewer");assertEquals("STALE",db.queryForObject("select status from inventory_correction where id=?",String.class,second));assertEquals(100,stock("on_hand"));}
 @Test void revokedApplicantCanBeRejectedOrWithdrawWithoutBusinessEffect(){UUID receipt=receipt(5),first=submit("RECEIPT_REVERSE",receipt),second=submit("RECEIPT_REVERSE",receipt);db.update("update membership set role='FINANCE' where tenant_id=? and username='requester'",tenant);assertEquals(403,assertThrows(ResponseStatusException.class,()->decide(first,"approve","reviewer")).getStatusCode().value());decide(first,"reject","reviewer");decide(second,"withdraw","requester");assertEquals("REJECTED",db.queryForObject("select status from inventory_correction where id=?",String.class,first));assertEquals("WITHDRAWN",db.queryForObject("select status from inventory_correction where id=?",String.class,second));assertEquals(105,stock("on_hand"));assertEquals(0,db.queryForObject("select count(*) from receipt_reversal where tenant_id=?",Integer.class,tenant));}
}
